select pg_advisory_xact_lock(hashtext('onboard:venexia'));
do $onboard$
declare cid uuid; pid uuid; aid uuid; tid uuid; payload jsonb := '{"roadmap":{"stack":{"architecture":{"title":"A tecnologia do novo site.","description":"Pacote 1: site institucional de página única, estático e rápido, com animações de entrada. O Pacote 2 acrescenta loja, estoque e pagamentos; o Pacote 3 transforma o catálogo num mural interativo.","inputs":[{"id":"site","brand":"","title":"Site institucional","tool":"HTML, CSS e JavaScript","detail":"Página única com produtos, Clube Namu, Best Off e oportunidade","href":"https://developer.mozilla.org/pt-BR/docs/Web/HTML"},{"id":"contato","brand":"resend","title":"Formulário de contato","tool":"Resend","detail":"Envio dos contatos por e-mail · previsto, desligado no protótipo","href":"https://resend.com"},{"id":"whatsapp","brand":"whatsapp","title":"Botão de WhatsApp","tool":"WhatsApp","detail":"Número da Venexia a confirmar · previsto para o site final","href":"https://business.whatsapp.com"}],"core":{"id":"core","brand":"no","title":"Site publicado pela nó","tool":"Vercel","detail":"Hospedagem em CDN com HTTPS · prevista para o site final","href":"https://vercel.com"},"services":[{"id":"dominio","brand":"","title":"Domínio","tool":"Domínio próprio","detail":"venexia.com.br apontado para o novo site após a aprovação","href":"https://venexia.com.br"},{"id":"seo","brand":"meta","title":"SEO e compartilhamento","tool":"Meta tags + Open Graph","detail":"Prévia ao compartilhar no WhatsApp e nas redes · prevista para o site final","href":"https://developers.facebook.com/docs/sharing/webmasters/"},{"id":"loja","brand":"supabase","title":"Loja, estoque e pedidos","tool":"Supabase","detail":"Pacote 2 · não incluído no Pacote 1","href":"https://supabase.com"}],"caption":"O protótipo navegável é o Pacote 1 pronto para aprovação. Hospedagem, domínio, loja e pagamentos dependem do pacote escolhido e ainda não foram ativados."}},"costs":[],"next_steps":{"presentation":{"phase_mode":"source","review_label":"Proposta em análise","review_description":"Três pacotes propostos; nenhum escolhido ainda.","prototype_title":"Navegue pelo novo site da Venexia.","editor_lock_reason":"O Editor fica bloqueado até a aprovação do pacote. Navegue pela aba Protótipo e envie suas observações à Maisis.","hero_title":"O novo site da Venexia, pronto para aprovação.","hero_description":"Explore o protótipo do site institucional, conheça a tecnologia e compare os três pacotes propostos.","infrastructure_title":"Três pacotes. Escolha o tamanho do próximo passo.","scope_options":[{"label":"Site institucional","badge":"Pacote 1","price":"R$ 1.500","tagline":"O site que você está vendo no protótipo, pronto para ir ao ar.","selected":false,"features":["Site novo em uma página: marca, produtos, Clube Namu, Best Off e oportunidade.","Formulário de contato e botão de WhatsApp (número a confirmar).","Animações de entrada, textos e cores, como no protótipo.","Prazo e suporte combinados com a Maisis."],"cta_label":"Quero o Pacote 1","cta_href":"https://wa.me/5511997151833?text=Ol%C3%A1%2C%20Thomas!%20Vi%20a%20proposta%20da%20Venexia%20no%20painel%20da%20n%C3%B3%20e%20quero%20seguir%20com%20o%20Pacote%201%20%E2%80%94%20Site%20institucional%20(R%24%201.500)."},{"label":"E-commerce","badge":"Pacote 2","price":"R$ 5.000","tagline":"Loja virtual completa para vender os produtos direto pelo site.","selected":false,"features":["Loja com catálogo dos produtos, carrinho e checkout.","Pagamentos por API, controle de estoque e logística de entrega.","Painel de produtos e pedidos, com o visual animado do Pacote 1.","Prazo e suporte combinados com a Maisis."],"cta_label":"Quero o Pacote 2","cta_href":"https://wa.me/5511997151833?text=Ol%C3%A1%2C%20Thomas!%20Vi%20a%20proposta%20da%20Venexia%20no%20painel%20da%20n%C3%B3%20e%20quero%20seguir%20com%20o%20Pacote%202%20%E2%80%94%20E-commerce%20(R%24%205.000)."},{"label":"Catálogo conceitual","badge":"Pacote 3","price":"R$ 8.000 a 10.000","tagline":"Uma vitrine de luxo: o catálogo vira um mural interativo.","selected":false,"features":["Catálogo em mural: produtos em nichos iluminados, como numa galeria.","Clique no produto e ele se expande com detalhes e preço.","Zoom, transições e componentes interativos: a experiência mais imersiva.","Prazo e suporte combinados com a Maisis."],"cta_label":"Quero o Pacote 3","cta_href":"https://wa.me/5511997151833?text=Ol%C3%A1%2C%20Thomas!%20Vi%20a%20proposta%20da%20Venexia%20no%20painel%20da%20n%C3%B3%20e%20quero%20seguir%20com%20o%20Pacote%203%20%E2%80%94%20Cat%C3%A1logo%20conceitual%20(R%24%208.000%20a%2010.000)."}],"scope_note":"Nenhum pacote foi escolhido ainda. Valores da proposta de 06/11/2026; prazos, suporte e custos de domínio e meio de pagamento são confirmados com a Maisis antes do fechamento.","hide_project_navigation":true},"task_details":{}},"references":["Site atual: https://venexia.com.br/ (página de lançamento, 1º/11/2026)","Apresentação institucional da Venexia (23 slides): textos, fotos e plano de marketing","Referência do Pacote 3: mural de produtos que expande ao clique","Protótipo: lp-institucional-v1 (Pacote 1)"],"tiers":{},"preferred_tier":null,"prototype_url":"/prototipos/venexia/lp-institucional-v1/index.html"},"tasks":[{"source_id":"p0-1","title":"Leitura da apresentação e do site atual","phase":"Fase 0 · Proposta","status":"concluido","note":"23 slides e a página de lançamento: textos, produtos e plano.","week":null,"position":0},{"source_id":"p0-2","title":"Proposta com três pacotes","phase":"Fase 0 · Proposta","status":"concluido","note":"Institucional, E-commerce e Catálogo conceitual.","week":null,"position":1},{"source_id":"p0-3","title":"Protótipo do site institucional","phase":"Fase 0 · Proposta","status":"concluido","note":"Disponível na aba Protótipo.","week":null,"position":2},{"source_id":"p0-4","title":"Apresentação pela Maisis","phase":"Fase 0 · Proposta","status":"a_fazer","note":"Reunião com a Venexia.","week":null,"position":3},{"source_id":"p0-5","title":"Escolha do pacote","phase":"Fase 0 · Proposta","status":"a_fazer","note":"Define o escopo das próximas fases.","week":null,"position":4},{"source_id":"p1-1","title":"Fotos originais dos produtos","phase":"Fase 1 · Conteúdo e identidade","status":"a_fazer","note":"As do protótipo foram recortadas da apresentação.","week":null,"position":5},{"source_id":"p1-2","title":"Revisão dos textos e do plano de marketing","phase":"Fase 1 · Conteúdo e identidade","status":"a_fazer","note":"Inclui a regra vigente da Venexia Experience.","week":null,"position":6},{"source_id":"p1-3","title":"Contatos e redes da Venexia","phase":"Fase 1 · Conteúdo e identidade","status":"a_fazer","note":"WhatsApp, e-mail de atendimento e Instagram.","week":null,"position":7},{"source_id":"p1-4","title":"Uso das marcas Namu e Best Off","phase":"Fase 1 · Conteúdo e identidade","status":"a_fazer","note":"Confirmar textos e logos autorizados pelos parceiros.","week":null,"position":8},{"source_id":"p2-1","title":"Ajustes após a aprovação","phase":"Fase 2 · Produção do site","status":"a_fazer","note":"Rodadas de revisão conforme o pacote.","week":null,"position":9},{"source_id":"p2-2","title":"Formulário de contato ativo","phase":"Fase 2 · Produção do site","status":"a_fazer","note":"Contatos chegando no e-mail da Venexia.","week":null,"position":10},{"source_id":"p2-3","title":"Testes em celular e computador","phase":"Fase 2 · Produção do site","status":"a_fazer","note":"Velocidade, animações, formulário e WhatsApp.","week":null,"position":11},{"source_id":"p3-1","title":"Domínio venexia.com.br apontado","phase":"Fase 3 · Publicação","status":"a_fazer","note":"Substitui a página de lançamento atual.","week":null,"position":12},{"source_id":"p3-2","title":"Site no ar e conferido","phase":"Fase 3 · Publicação","status":"a_fazer","note":"Formulário, WhatsApp e velocidade no endereço final.","week":null,"position":13},{"source_id":"p3-3","title":"Início do suporte","phase":"Fase 3 · Publicação","status":"a_fazer","note":"Período conforme o pacote escolhido.","week":null,"position":14}]}'::jsonb; task jsonb; details jsonb := '{}'::jsonb;
begin
  select id into aid from public.agencies where slug='maisis';
  if aid is null then raise exception 'Agency % not found', 'maisis'; end if;
  if not exists(select 1 from public.agencies where id=aid and name='Maisis Publicidade' and active) then raise exception 'Agency identity/status mismatch'; end if;
  select id into cid from public.clients where slug='venexia';
  if cid is null then
    if exists(select 1 from public.clients where name ilike '%venex%') then raise exception 'Review existing similar client'; end if;
    insert into public.clients(name,slug) values('Venexia','venexia') returning id into cid;
  elsif not exists(select 1 from public.clients where id=cid and name='Venexia') then raise exception 'Client identity mismatch'; end if;
  if (select count(*) from public.projects where client_id=cid and name='Novo site Venexia')>1 then raise exception 'Duplicate project'; end if;
  select id into pid from public.projects where client_id=cid and name='Novo site Venexia';
  if pid is null then
    insert into public.projects(client_id,name,niche,lead_status,project_status,modules,access_status,access_released_at)
    values(cid,'Novo site Venexia','venda direta · bem-estar e beleza','JANELA_DE_DECISAO','EM_REVISAO_CLIENTE','{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado","versoes":"bloqueado","marca":"bloqueado"}'::jsonb,'ATIVO_ATE_FIM_DO_PROJETO',now()) returning id into pid;
  else
    update public.projects set niche='venda direta · bem-estar e beleza' where id=pid and niche is distinct from 'venda direta · bem-estar e beleza';
  end if;
  if exists(select 1 from public.agency_projects where project_id=pid and agency_id<>aid) then raise exception 'Project already assigned to another agency'; end if;
  insert into public.agency_projects(agency_id,project_id) values(aid,pid) on conflict(project_id) do nothing;
  for task in select value from jsonb_array_elements(payload->'tasks') loop
    tid := null;
    select k.id into tid from public.kanban_items k where k.project_id=pid and k.title=task->>'title';
    if tid is null then
      insert into public.kanban_items(project_id,title,phase,status,position)
      values(pid,task->>'title',task->>'phase',(task->>'status')::public.kanban_status,(task->>'position')::integer) returning id into tid;
    else
      update public.kanban_items set phase=task->>'phase',position=(task->>'position')::integer
       where id=tid and (phase,position) is distinct from (task->>'phase',(task->>'position')::integer);
    end if;
    details := details || jsonb_build_object(tid::text,jsonb_build_object('source_id',task->>'source_id','note',task->>'note','week',task->'week'));
  end loop;
  insert into public.roadmaps(project_id,stack,costs,next_steps,"references",tiers,prototype_url,published_at)
  values(pid,payload->'roadmap'->'stack',payload->'roadmap'->'costs',(payload->'roadmap'->'next_steps') || jsonb_build_object('task_details',details),payload->'roadmap'->'references','{}',payload->'roadmap'->>'prototype_url',now())
  on conflict(project_id) do update set stack=excluded.stack,costs=excluded.costs,next_steps=excluded.next_steps,"references"=excluded."references",prototype_url=excluded.prototype_url,published_at=coalesce(roadmaps.published_at,excluded.published_at);
end $onboard$;
commit;
select c.id client_id,p.id project_id,a.id agency_id,c.name,p.lead_status,p.project_status,p.access_status,p.access_released_at,p.modules,r.prototype_url,
(select count(*) from public.kanban_items where project_id=p.id) tasks,
(select count(*) from public.kanban_items where project_id=p.id and status='concluido') completed,
(select count(*) from public.memberships where client_id=c.id) client_memberships
from public.clients c join public.projects p on p.client_id=c.id join public.agency_projects ap on ap.project_id=p.id join public.agencies a on a.id=ap.agency_id join public.roadmaps r on r.project_id=p.id where c.slug='venexia';
